from pathlib import Path
import json, re

root = Path(__file__).parent
old = (root / 'Maqueta_mapa_castilla.html').read_text(encoding='utf-8')
images = re.search(r'const imageData=(\{.*?\});const items=', old).group(1)
map_image = re.search(r'background:#152116 url\("(data:image/webp;base64,[^"]+)"\)', old).group(1)
icons = {n: v for n, v in re.findall(r'\.resource-(icono_[a-z_]+)\{background-image:url\("(data:image/webp;base64,[^"]+)"\)\}', old)}
template = '''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fulgor Medieval — construir en Castilla</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#15120f;color:#ecddb9;font-family:Georgia,serif}.viewport{position:relative;overflow:hidden;background:#151a14;max-width:1600px;aspect-ratio:16/10;min-height:540px;margin:auto}.terrain{position:absolute;width:300%;aspect-ratio:8/5;left:50%;top:50%;transform:translate(-50%,-50%)}.terrain>img{width:100%;height:100%;display:block}.hex{position:absolute;transform:translate(-50%,-50%);width:5.2%;height:7.4%;clip-path:polygon(25% 0,75% 0,100% 50%,75% 100%,25% 100%,0 50%);background:#ffe29114;border:0;cursor:pointer}.hex:hover,.hex:focus-visible,.hex.active{background:#ffe58065;outline:0;filter:brightness(1.2)}.hex::after{content:' ';position:absolute;inset:7%;clip-path:polygon(25% 0,75% 0,100% 50%,75% 100%,25% 100%,0 50%,25% 0,25% 5%,5% 50%,27% 93%,73% 93%,95% 50%,73% 5%,27% 5%);background:#ffdb79}.hex.occupied{background:#e6c06575}.marker{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);max-width:66%;max-height:70%;object-fit:contain;pointer-events:none;filter:drop-shadow(0 2px 3px #000)}.top{position:absolute;inset:0 0 auto;display:flex;justify-content:space-between;align-items:flex-start;gap:8px;pointer-events:none}.realm,.resources,.bar,.legend{background:linear-gradient(145deg,#3b2a1d,#211711 55%,#39281a);border:3px double #aa8950;box-shadow:0 3px 12px #000b,inset 0 0 8px #0009}.realm{display:flex;align-items:center;gap:10px;padding:8px 20px 8px 10px}.shield{background:#7b1619;color:#f0c355;border:2px solid #c3974d;width:46px;height:58px;clip-path:polygon(0 0,100% 0,100% 72%,50% 100%,0 72%);display:grid;place-items:center;font-size:28px}.realm strong{display:block;font-size:23px;letter-spacing:1px;color:#efdaa8}.realm small{color:#baa57f;font-size:10px;letter-spacing:1px}.resources{padding:12px 18px;display:flex;gap:18px;font-size:17px}.resource-icon{display:inline-block;width:23px;height:23px;object-fit:contain;vertical-align:middle;margin-right:3px}.bar{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);width:min(94%,1100px);height:150px;display:flex;align-items:stretch;gap:7px;padding:9px}.list{display:flex;gap:7px;flex:1;min-width:0}.building{position:relative;flex:1;min-width:0;background:radial-gradient(ellipse at 50% 44%,#454038,#181411 75%);border:2px solid #75613e;padding:0;cursor:pointer;overflow:hidden}.building img{display:block;width:100%;height:100%;object-fit:contain;object-position:center}.building.active{border-color:#f2d27f;box-shadow:0 0 10px #f5d68499}.building .icon{position:absolute;bottom:4px;left:50%;transform:translateX(-50%);background:#251d17;border:1px solid #8d7447;width:32px;height:28px;display:grid;place-items:center}.building .icon img{width:21px;height:21px}.label{position:absolute;bottom:180px;left:50%;transform:translateX(-50%);background:#251b14e8;border:1px solid #967a4c;padding:7px 14px;font-size:12px;letter-spacing:.3px;white-space:nowrap}.legend{position:absolute;right:4%;top:15%;width:210px;max-height:48%;display:none;color:#35281b;background:linear-gradient(145deg,#e1d0a6,#bca174);border:5px ridge #89724b;padding:12px;overflow:auto}.legend.visible{display:block}.legend h2{font-size:16px;margin:0 0 7px}.legend .row{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #a78d62;padding:5px 0;font-size:12px}.legend .result{font-size:19px;padding:7px 0;color:#302013}.legend button{width:100%;padding:7px;background:#503221;color:#f5e0ac;border:2px ridge #9d8152;font-family:inherit}.legend button:disabled{opacity:.5}.legend small{font-size:11px}.note{max-width:1100px;margin:12px auto;padding:0 12px;font:13px Arial,sans-serif;color:#bbaf94;line-height:1.5}.coords{position:absolute;top:12%;left:50%;transform:translateX(-50%);background:#211a13cc;color:#f0dca7;padding:6px 10px;font-size:12px;border:1px solid #947546}.toast{color:#73562e;font-size:11px;padding-top:5px}@media(max-width:700px){.viewport{min-height:620px}.realm strong{font-size:15px}.realm{padding:6px}.shield{width:33px;height:42px;font-size:21px}.resources{gap:5px;padding:8px;font-size:13px}.resource-icon{width:18px;height:18px}.bar{height:105px;bottom:8px;padding:5px;gap:3px}.list{gap:3px}.building .icon{width:25px;height:22px}.building .icon img{width:17px;height:17px}.label{bottom:123px}.legend{top:15%;width:165px;padding:8px}.legend h2{font-size:14px}.terrain{width:400%}}
</style></head><body><main class="viewport"><div class="terrain" id="terrain"><img id="map" alt="Captura del mapa de campaña de Unity"><div id="cells"></div></div><div class="top"><div class="realm"><div class="shield">♜</div><div><small>REINO DE</small><strong>CASTILLA</strong></div></div><div class="resources" id="resources"></div></div><div class="coords">TERRITORIO DE LA CIUDAD · PRIMER ANILLO</div><aside class="legend" id="legend" aria-live="polite"><h2 id="title"></h2><small id="cellname"></small><div class="row"><span>Terreno</span><b id="passive"></b></div><div class="row"><span>Construcción</span><b id="active"></b></div><div class="row"><span>Bonificación</span><b id="bonus"></b></div><div class="result" id="total"></div><div class="row"><span>Coste orientativo</span><b id="cost"></b></div><p><small id="detail"></small></p><button id="place">CONSTRUIR AQUÍ</button><div class="toast" id="toast"></div></aside><div class="label" id="label">ELIGE UN EDIFICIO Y SEÑALA UNA CASILLA</div><div class="bar"><div class="list" id="list"></div></div></main><p class="note">Maqueta interactiva: el fondo es una captura real de Unity. Los puntos de selección, los edificios superpuestos y los rendimientos son simulados para probar el diseño; aún no modifican las casillas del juego.</p>
<script>
const imageData=__IMAGES__, mapImage=__MAP__, iconData=__ICONS__;
document.querySelector('#map').src=mapImage;
const icon=(id)=>'<img class="resource-icon" alt="'+id+'" src="'+iconData['icono_'+id]+'">';
const types=[{name:'Vivienda sencilla',img:'Vivienda_sencilla',resource:'poblacion',amount:2,terrain:['llanura','colina'],cost:'madera',costn:10},{name:'Huerto o campo',img:'Huerto_o_campo',resource:'grano',amount:3,terrain:['llanura'],cost:'madera',costn:15},{name:'Leñera',img:'Lenera',resource:'madera',amount:3,terrain:['bosque'],cost:'madera',costn:5},{name:'Cantera sencilla',img:'Cantera_sencilla',resource:'piedra',amount:3,terrain:['colina'],cost:'madera',costn:10},{name:'Puesto de intercambio',img:'Puesto_de_intercambio',resource:'oro',amount:2,terrain:['llanura','colina','bosque'],cost:'madera',costn:15},{name:'Campo de milicias',img:'Campo_de_milicias',resource:'mano_de_obra',amount:1,terrain:['llanura','colina'],cost:'madera',costn:10}];
const cells=[{x:47.5,y:44.7,kind:'llanura'},{x:52.5,y:44.7,kind:'llanura'},{x:54.8,y:49.8,kind:'llanura'},{x:52.5,y:55,kind:'colina'},{x:47.5,y:55,kind:'llanura'},{x:45.2,y:49.8,kind:'llanura'}];let selected=1,hover=null;const list=document.querySelector('#list'),legend=document.querySelector('#legend'),cellbox=document.querySelector('#cells');document.querySelector('#resources').innerHTML=[['grano',28],['madera',45],['piedra',30],['oro',25],['mano_de_obra',18]].map(a=>'<span>'+icon(a[0])+a[1]+'</span>').join('');
function drawBar(){list.innerHTML='';types.forEach((t,i)=>{const b=document.createElement('button');b.className='building'+(i===selected?' active':'');b.setAttribute('aria-label',t.name);b.title=t.name;b.innerHTML='<img src="'+imageData[t.img]+'" alt=""><span class="icon">'+icon(t.resource)+'</span>';b.onclick=()=>{selected=i;document.querySelector('#label').textContent=t.name.toUpperCase()+' · SEÑALA UNA CASILLA';drawBar();if(hover!==null)show(hover)};list.appendChild(b)})}
function drawCells(){cellbox.innerHTML='';cells.forEach((c,i)=>{const b=document.createElement('button');b.className='hex'+(i===hover?' active':'')+(c.building?' occupied':'');b.style.left=c.x+'%';b.style.top=c.y+'%';b.setAttribute('aria-label','Casilla '+(i+1)+' · '+c.kind);if(c.building!==undefined){let img=document.createElement('img');img.className='marker';img.src=imageData[types[c.building].img];img.alt='';b.appendChild(img)}b.onmouseenter=()=>show(i);b.onfocus=()=>show(i);b.onclick=()=>show(i);cellbox.appendChild(b)})}
function show(i){hover=i;const c=cells[i],t=types[selected],passive=c.kind==='colina'?'piedra':c.kind==='bosque'?'madera':'grano',ok=t.terrain.includes(c.kind)&&c.building===undefined;legend.classList.add('visible');document.querySelector('#title').textContent=t.name;document.querySelector('#cellname').textContent='Casilla '+(i+1)+' · '+c.kind;document.querySelector('#passive').innerHTML=icon(passive)+' +1';document.querySelector('#active').innerHTML=icon(t.resource)+' +'+t.amount;document.querySelector('#bonus').textContent='—';document.querySelector('#total').innerHTML=(passive===t.resource?icon(passive)+' +'+(1+t.amount):icon(passive)+' +1　'+icon(t.resource)+' +'+t.amount)+' <small>por turno</small>';document.querySelector('#cost').innerHTML=icon(t.cost)+' '+t.costn;document.querySelector('#detail').textContent=c.building!==undefined?'Esta casilla ya está ocupada.':ok?'Pulsa para colocar el edificio de prueba.':'Este edificio necesita otro terreno.';document.querySelector('#place').disabled=!ok;document.querySelector('#toast').textContent='';[...cellbox.children].forEach((button,n)=>button.classList.toggle('active',n===i))}
document.querySelector('#place').onclick=()=>{if(hover===null)return;const c=cells[hover],t=types[selected];if(c.building!==undefined||!t.terrain.includes(c.kind))return;c.building=selected;drawCells();show(hover);document.querySelector('#toast').textContent='Obra colocada en la maqueta.'};drawBar();drawCells();
</script></body></html>'''
template = template.replace('__IMAGES__', images).replace('__MAP__', json.dumps(map_image)).replace('__ICONS__', json.dumps(icons))
(root / 'Maqueta_mapa_castilla_v2.html').write_text(template, encoding='utf-8')
print('Creada maqueta V2 con recursos integrados')
